<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue'; import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue'; import {Head,router} from '@inertiajs/vue3'; import {ref} from 'vue';
const props=defineProps({donations:Object,filters:Object}); const status=ref(props.filters?.status||''); const search=ref(props.filters?.search||''); const money=v=>'₦'+Number(v||0).toLocaleString('en-NG');
function filter(){router.get('/admin/fundraising/donations',{status:status.value,search:search.value},{preserveState:true,replace:true});}
function review(id,action){const note=prompt('Optional admin note:')||''; if(confirm(`${action} this bank transfer?`)) router.post(`/admin/fundraising/donations/${id}/verify`,{action,admin_note:note});}
</script>
<template><PublicLayout><Head title="Fundraising Donations"/><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-8"><h1 class="text-3xl font-extrabold text-white">Donations</h1></div><AdminQuickLinks/></section><main class="mx-auto max-w-7xl px-5 py-8"><div class="flex flex-wrap items-center justify-between gap-3 mb-6"><p class="text-sm text-gray-600">Review and manage campaign donations and payment verification.</p><div class="flex flex-wrap gap-2"><a href="/admin/fundraising/donations" class="rounded-lg border border-gray-300 px-4 py-2 text-sm font-bold hover:bg-gray-50">Donations</a><a href="/admin/fundraising/pledges" class="rounded-lg border border-gray-300 px-4 py-2 text-sm font-bold hover:bg-gray-50">Pledges</a><a href="/admin/fundraising/create" class="rounded-lg bg-[#006B3C] px-4 py-2 text-sm font-bold text-white hover:bg-[#00552f]">Create campaign</a></div></div><div class="mb-5 flex flex-wrap gap-3"><input v-model="search" @keyup.enter="filter" placeholder="Search donor or reference" class="rounded-lg border-gray-300"/><select v-model="status" @change="filter" class="rounded-lg border-gray-300"><option value="">All statuses</option><option value="success">Successful</option><option value="pending">Pending</option><option value="failed">Failed</option></select><button @click="filter" class="rounded-lg border px-4 py-2">Filter</button></div><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50"><tr><th class="p-3">Date</th><th>Campaign</th><th>Donor</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="d in donations.data" :key="d.id" class="border-t"><td class="p-3">{{d.paid_at||d.created_at}}</td><td>{{d.campaign}}</td><td>{{d.donor_name}}<small class="block text-gray-500">{{d.donor_email}}</small></td><td>{{money(d.amount)}}</td><td>{{d.method}}</td><td>{{d.reference}}</td><td>{{d.status}}</td><td v-if="d.method==='bank_transfer'&&d.status==='pending'"><button @click="review(d.id,'approve')" class="mr-2 font-bold text-green-700">Approve</button><button @click="review(d.id,'reject')" class="font-bold text-red-700">Reject</button></td><td v-else>—</td></tr></tbody></table></div></main></PublicLayout></template>
